"""Provided pathfinding helpers. Students normally do not edit this file."""

from __future__ import annotations

from collections import deque
from heapq import heappop, heappush
from typing import Iterable

from treasure_explorer.model import Action, Observation


MOVES = (
    (Action.MOVE_UP, -1, 0),
    (Action.MOVE_DOWN, 1, 0),
    (Action.MOVE_LEFT, 0, -1),
    (Action.MOVE_RIGHT, 0, 1),
)
TERRAIN_COST = {".": 1, "S": 1, "E": 1, "T": 1, "M": 4, "W": 7}


def in_bounds(grid: tuple[str, ...], position: tuple[int, int]) -> bool:
    row, col = position
    return 0 <= row < len(grid) and 0 <= col < len(grid[0])


def known_neighbors(
    obs: Observation,
    position: tuple[int, int],
    forbidden: Iterable[tuple[int, int]] = (),
):
    """Yield known, traversable neighbours and the cost of entering each one."""
    blocked = set(forbidden)
    for action, dr, dc in MOVES:
        nxt = position[0] + dr, position[1] + dc
        if not in_bounds(obs.grid, nxt) or nxt in blocked:
            continue
        tile = obs.grid[nxt[0]][nxt[1]]
        if tile in TERRAIN_COST:
            yield nxt, action, TERRAIN_COST[tile]


def _reconstruct(
    parent: dict[tuple[int, int], tuple[tuple[int, int], Action] | None],
    start: tuple[int, int],
    goal: tuple[int, int],
) -> list[Action]:
    if goal not in parent:
        return []
    actions: list[Action] = []
    current = goal
    while current != start:
        previous, action = parent[current]  # type: ignore[misc]
        actions.append(action)
        current = previous
    actions.reverse()
    return actions


def bfs_path(
    obs: Observation,
    start: tuple[int, int],
    goal: tuple[int, int] | None,
    forbidden: Iterable[tuple[int, int]] = (),
) -> list[Action]:
    """Return a minimum-step path through currently known cells."""
    if goal is None or goal == start:
        return []
    queue = deque([start])
    parent: dict[tuple[int, int], tuple[tuple[int, int], Action] | None] = {start: None}
    while queue:
        current = queue.popleft()
        if current == goal:
            break
        for nxt, action, _ in known_neighbors(obs, current, forbidden):
            if nxt not in parent:
                parent[nxt] = current, action
                queue.append(nxt)
    return _reconstruct(parent, start, goal)


def dijkstra_path(
    obs: Observation,
    start: tuple[int, int],
    goal: tuple[int, int] | None,
    forbidden: Iterable[tuple[int, int]] = (),
) -> tuple[list[Action], int]:
    """Return a minimum-energy path and its terrain-entry cost."""
    if goal is None:
        return [], 10**9
    if goal == start:
        return [], 0
    frontier = [(0, start)]
    distance = {start: 0}
    parent: dict[tuple[int, int], tuple[tuple[int, int], Action] | None] = {start: None}
    while frontier:
        cost, current = heappop(frontier)
        if cost != distance[current]:
            continue
        if current == goal:
            break
        for nxt, action, step_cost in known_neighbors(obs, current, forbidden):
            candidate = cost + step_cost
            if candidate < distance.get(nxt, 10**9):
                distance[nxt] = candidate
                parent[nxt] = current, action
                heappush(frontier, (candidate, nxt))
    if goal not in distance:
        return [], 10**9
    return _reconstruct(parent, start, goal), distance[goal]


def known_frontiers(obs: Observation) -> list[tuple[int, int]]:
    """Known walkable cells adjacent to at least one unknown cell."""
    result = []
    for row, line in enumerate(obs.grid):
        for col, tile in enumerate(line):
            if tile not in TERRAIN_COST:
                continue
            if any(
                in_bounds(obs.grid, (row + dr, col + dc))
                and obs.grid[row + dr][col + dc] == "?"
                for _, dr, dc in MOVES
            ):
                result.append((row, col))
    return result


def safe_known_move(obs: Observation) -> Action:
    """Deterministic last resort; normally a policy should return a planned move."""
    for _, action, _ in known_neighbors(obs, obs.position):
        return action
    return Action.MOVE_RIGHT
